        }
      ]
    }
  },
  {
    "json": {
      "sourceKind": "ats",
      "demoOnly": true,
      "rows": [
        {
          "recordType": "board_health",
          "boardKey": "greenhouse:sample-board",
          "ats": "greenhouse",
          "sourceUrl": null,
          "inputKind": "customer_snapshot",
          "sourceHealthy": true,
          "complete": true,
          "activeJobs": 0,
          "baseline": false,
